package sub

import (
	"crypto/x509"
	"encoding/json"
	"encoding/pem"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/mhsanaei/3x-ui/v2/database/model"
	"github.com/xtls/xray-core/infra/conf"
)

// Browser fixtures contain ephemeral keys, stay outside the source tree, and
// are generated by tests/dialect11/native-defaults-review-ui.js. This consumes
// the actual post-transition browser output rather than recreating its logic.
func TestNativeUIOrbitRoundtripExports(t *testing.T) {
	dir := os.Getenv("NATIVE_UI_ORBIT_FIXTURES")
	if dir == "" {
		t.Skip("set NATIVE_UI_ORBIT_FIXTURES to the completed full-page browser review directory")
	}
	files, err := filepath.Glob(filepath.Join(dir, "*-panel-settings.json"))
	if err != nil || len(files) < 10 {
		t.Fatalf("expected complete Orbit transition fixtures, got %d: %v", len(files), err)
	}
	for _, file := range files {
		t.Run(filepath.Base(file), func(t *testing.T) {
			data, err := os.ReadFile(file)
			if err != nil {
				t.Fatal(err)
			}
			var settings struct {
				Clients   []model.Client `json:"clients"`
				Transport string         `json:"transport"`
				TLS       struct {
					Certificate []string `json:"certificate"`
				} `json:"tls"`
			}
			if err = json.Unmarshal(data, &settings); err != nil || len(settings.Clients) != 1 {
				t.Fatal("invalid browser client fixture", err)
			}
			client := settings.Clients[0]
			inbound := &model.Inbound{Protocol: model.Protocol("orbit"), Listen: "127.0.0.1", Port: 29091, Tag: "ui-orbit-review", Remark: "UI Orbit review", Settings: string(data), StreamSettings: "{}", Sniffing: "{}", Enable: true}
			outbounds, err := nativeClientOutbounds(inbound, client, "127.0.0.1")
			if err != nil {
				t.Fatal(err)
			}
			nativeTestOutboundsBuild(t, outbounds)
			if settings.Transport == "ws" || settings.Transport == "wss" {
				outbound := outbounds[0]["settings"].(map[string]any)
				name, _ := outbound["peer"].(string)
				if name == "" {
					name, _ = outbound["host"].(string)
				}
				// This verifies the inner Orbit TLS identity only. The WSS
				// fixture uses a synthetic outer certificate; these parser
				// checks do not establish its trust or hostname validity.
				block, _ := pem.Decode([]byte(strings.Join(settings.TLS.Certificate, "\n")))
				if block == nil {
					t.Fatal("browser fixture inner certificate missing")
				}
				leaf, err := x509.ParseCertificate(block.Bytes)
				if err != nil {
					t.Fatal(err)
				}
				if err = leaf.VerifyHostname(name); err != nil {
					t.Fatalf("exported peer %q does not match browser inner certificate: %v", name, err)
				}
			}

			service := NewSubJsonService("", "", "", "", NewSubService(false, "-ieo"))
			configs, err := service.getNativeConfig(inbound, client, "127.0.0.1")
			if err != nil || len(configs) != 1 {
				t.Fatalf("complete JSON count=%d err=%v", len(configs), err)
			}
			var config conf.Config
			if err = json.Unmarshal(configs[0], &config); err != nil {
				t.Fatal(err)
			}
			if _, err = config.Build(); err != nil {
				t.Fatal(err)
			}
			if inbound.Settings != string(data) {
				t.Fatal("export mutated saved mode material")
			}
		})
	}
}
